# Identify venmo friends to remove (not in phone friends)
phone_emails = {c['email'] for c in phone_friends}
venmo_emails = {f['email'] for f in venmo_friends}

to_remove = [f for f in venmo_friends if f['email'] not in phone_emails]
to_add = [c for c in phone_friends if c['email'] not in venmo_emails]

print("To remove:")
for f in to_remove:
    print(f['first_name'], f['last_name'], f['email'])
print("\nTo add:")
for c in to_add:
    print(c['first_name'], c['last_name'], c['email'])

