for pl in playlists:
    pl_id = pl['playlist_id']
    pl_detail = apis.spotify.show_playlist(playlist_id=pl_id, access_token=spotify_login['access_token'])
    if 'songs' in pl_detail:
        for song in pl_detail['songs']:
            sid = song['id']
            if sid not in all_songs:
                all_songs[sid] = {'title': song['title'], 'artist_ids': song['artist_ids'], 'playlist_ids': set()}
            all_songs[sid]['playlist_ids'].add(pl_id)
    else:
        print("Error getting playlist", pl_id, pl_detail)
print("Total unique songs:", len(all_songs))
