# Search for each archive song to get its song_id
archive_song_ids = []
for song in songs_to_archive:
    query = f"{song['title']} {song['artist']}"
    results = apis.spotify.search_songs(query=query, access_token=login_result["access_token"], page_limit=20)
    # Find the exact match by title and artist
    found = None
    for s in results:
        if s['title'].lower() == song['title'].lower():
            # Check if any artist matches
            for art in s['artists']:
                if art['name'].lower() == song['artist'].lower():
                    found = s
                    break
        if found:
            break
    if found:
        archive_song_ids.append(found['song_id'])
        print(f"Found: {song['title']} by {song['artist']} -> song_id {found['song_id']}")
