# Verify all playlists after removal and confirm "Old Songs" has all archived songs
# Fetch all playlists again
all_playlists_after = []
page_index = 0
while True:
    page = apis.spotify.show_playlist_library(access_token=login_result["access_token"], page_index=page_index, page_limit=20)
    all_playlists_after.extend(page)
    if len(page) < 20:
        break
    page_index += 1

# Check that no archived song remains in any playlist except "Old Songs" (id 654)
archived_ids = {song_id for song_id, _, _ in song_ids_to_archive}
issues = []
for pl in all_playlists_after:
    pl_id = pl["playlist_id"]
    pl_title = pl["title"]
    # Get song IDs for this playlist (the library response may include song_ids directly)
    song_ids = pl.get("song_ids", [])
    if pl_id != 654:
        for sid in song_ids:
            if sid in archived_ids:
                issues.append(f"Playlist {pl_title} (id {pl_id}) still contains archived song {sid}")
    else:
        # Check that all archived songs are present
        missing = archived_ids - set(song_ids)
        if missing:
            issues.append(f"Old Songs playlist missing archived songs: {missing}")

if issues:
    print("ISSUES FOUND:")
    for issue in issues:
        print(issue)
else:
    print("All archived songs removed from all playlists except 'Old Songs', and 'Old Songs' contains all archived songs.")

# Print summary of playlists
for pl in all_playlists_after:
    print(f"Playlist {pl['playlist_id']}: {pl['title']} - {len(pl.get('song_ids', []))} songs")

