# Let's parse the old songs list from the file content.
old_songs_text = file_info['content']
old_songs = []
for line in old_songs_text.strip().split('\n'):
    if line.startswith('- '):
        song_str = line[2:]
        # Split on " by " to get title and artist part
        if ' by ' in song_str:
            title, artists_str = song_str.split(' by ', 1)
            old_songs.append({'title': title.strip(), 'artists': artists_str.strip()})
        else:
            old_songs.append({'title': song_str.strip(), 'artists': ''})

print(f"Parsed {len(old_songs)} old songs:")
for s in old_songs:
    print(s)

