steps.code:
# Search for each old song and find the exact match
old_song_ids = {}
for song in old_songs:
    query = f"{song['title']} {song['artist']}"
    results = apis.spotify.search_songs(query=query, access_token=spotify_login['access_token'])
    # Find exact match: title matches and artist set matches
    expected_artists = set([a.strip() for a in song['artist'].split(',')])
    found = None
    for r in results:
        if r['title'] == song['title']:
            result_artists = set([a['name'] for a in r['artists']])
            if result_artists == expected_artists:
                found = r
                break
    if found:
        old_song_ids[song['title']] = found['song_id']
        print(f"Found: {song['title']} -> song_id {found['song_id']}")
    else:
        print(f"NOT FOUND: {song['title']} by {song['artist']}")

print(f"\nTotal matched: {len(old_song_ids)}")

