for pl in playlists:
    pl_id = pl['playlist_id']
    for song_id in pl['song_ids']:
        if song_id in archive_song_ids:
            result = apis.spotify.remove_song_from_playlist(playlist_id=pl_id, song_id=song_id, access_token=spotify_token)
