steps.code:
# Verify all original playlists no longer contain any of the 13 archived songs
target_song_ids = {4, 22, 69, 92, 219, 245, 265, 278, 295, 298, 299, 320, 324}
for pid in range(513, 520):
    pl = apis.spotify.show_playlist(playlist_id=pid, access_token=spotify_token)
    song_ids = {song['id'] for song in pl['songs']}
    remaining = song_ids & target_song_ids
    print(f"Playlist {pid} ({pl['title']}): remaining target songs = {remaining}")

